import sys

NXT = {
    (0, 0): 0, (0, 1): 1,
    (1, 0): 2, (1, 1): 1,
    (2, 0): 0, (2, 1): 3,
    (3, 0): 3, (3, 1): 3,
}

def count_upto(N):
    # numbers x in [0, N] whose binary form contains "101"
    if N <= 0:
        return 0
    bits = bin(N)[2:]
    free = [0, 0, 0, 0]   # counts of prefixes already strictly smaller than N, by automaton state
    tight = 0             # automaton state of the prefix equal to N's prefix
    for ch in bits:
        b = int(ch)
        new = [0, 0, 0, 0]
        for s in range(4):
            if free[s]:
                for d in (0, 1):
                    new[NXT[(s, d)]] += free[s]
        if b == 1:
            new[NXT[(tight, 0)]] += 1
        tight = NXT[(tight, b)]
        free = new
    return free[3] + (1 if tight == 3 else 0)

def main():
    L, R = map(int, sys.stdin.read().split())
    print(count_upto(R) - count_upto(L - 1))

main()

